95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    public Integer getHouseholdSize() {
143	        return this.householdSize;
144	    }
145	
146	    public void setHouseholdSize(Integer householdSize) {
147	        this.householdSize = householdSize;
148	    }
149	
150	    public String getMembershipNumber() {
151	        return this.membershipNumber;
152	    }
153	
154	    public void setMembershipNumber(String membershipNumber) {
155	        this.membershipNumber = membershipNumber;
156	    }
157	
158	    public Boolean getBulkSignupWarning() {
159	        return this.bulkSignupWarning;
160	    }
161	
162	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
163	        this.bulkSignupWarning = bulkSignupWarning;
164	    }
165	
166	    /**
167	     * The derived key that duplicate detection compares owners by, formed as the normalized
168	     * telephone, the (lower-cased) email or an empty string when absent, and the household id or an
169	     * empty string when absent, joined with {@code '|'}. Two owners are duplicates only when their
170	     * whole identity keys are equal, so members of one household with different telephones (and hence
171	     * different keys) are not duplicates. Derived on read from the stored, already-normalized fields.
172	     *
173	     * @return the derived identity key
174	     */
175	    public String getIdentityKey() {
176	        return (this.telephone == null ? "" : this.telephone) + '|'
177	            + (this.email == null ? "" : this.email) + '|'
178	            + (this.householdId == null ? "" : this.householdId);
179	    }
180	
181	    protected Set<Pet> getPetsInternal() {
182	        if (this.pets == null) {
183	            this.pets = new HashSet<>();
184	        }
185	        return this.pets;
186	    }
187	
188	    protected void setPetsInternal(Set<Pet> pets) {
189	        this.pets = pets;
190	    }
191	
192	    public List<Pet> getPets() {
