218	     * Return the Pet with the given name, or null if none found for this Owner.
219	     *
220	     * @param name to test
221	     * @return true if pet name is already in use
222	     */
223	    public Pet getPet(String name, boolean ignoreNew) {
224	        name = name.toLowerCase();
225	        for (Pet pet : getPetsInternal()) {
226	            if (!ignoreNew || !pet.isNew()) {
227	                String compName = pet.getName();
228	                compName = compName.toLowerCase();
229	                if (compName.equals(name)) {
230	                    return pet;
231	                }
232	            }
233	        }
234	        return null;
235	    }
236	
237	    public Pet getPet(Integer petId) {
238	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
239	    }
240	
241	    @Override
242	    public String toString() {
