17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	
21	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Produces the canonical stored form of an owner's telephone number in E.164.
26	 * <p>
27	 * Centralising this here keeps the REST controllers thin: they simply delegate to
28	 * {@link #normalize(String)} both when canonicalising an incoming value before it is
29	 * persisted and when comparing values to detect duplicates, so the two always agree.
30	 * <p>
31	 * The canonical form is E.164: a leading {@code '+'} and country code are kept when
32	 * present, otherwise country code {@code '+61'} is assumed and a single leading
33	 * {@code '0'} is dropped from the national digits. Spaces, dashes and brackets are
34	 * stripped. The result must carry 8 to 15 digits after the {@code '+'}; anything that
35	 * cannot form valid E.164 is rejected with {@link InvalidTelephoneException} (a 400).
36	 * Because a value already in E.164 form re-normalizes to itself, comparing normalized
37	 * values reliably detects duplicate telephones.
38	 * <p>
39	 * {@link #normalizeAndValidate(String)} additionally enforces the national-number length
40	 * expected for the country code ({@code '+61'} requires 9 national digits, {@code '+1'}
41	 * requires 10) and is used to validate a client-supplied value on create; plain
42	 * {@link #normalize(String)} keeps tolerating legacy stored numbers so it can still be used
43	 * to canonicalise existing values for duplicate comparison.
44	 */
45	@Component
46	public class TelephoneNormalizer {
47	
48	    private static final String DEFAULT_COUNTRY_CODE = "61";
49	
50	    /**
51	     * Required national-number length (the digits after the {@code '+'} and country code) for each
52	     * country code we know how to size. E.164 country codes form a prefix-free set, so at most one
53	     * of these is a prefix of any given number. Country codes not listed here are only subject to
54	     * the generic 8-to-15 total-length rule.
55	     */
56	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY_CODE = Map.of(
57	        "1", 10,
58	        DEFAULT_COUNTRY_CODE, 9);
59	
60	    /**
61	     * Normalizes the supplied telephone value to its canonical E.164 stored form.
62	     * Spaces, dashes and brackets are stripped; a leading {@code '+'} and country code
63	     * are preserved when present, otherwise {@code '+61'} is assumed and a single leading
64	     * {@code '0'} is dropped from the national digits. Values that differ only in
65	     * formatting therefore normalize to the same result.
66	     *
67	     * @param telephone the raw telephone value (may be {@code null})
68	     * @return the normalized E.164 telephone, or {@code null} if the input was {@code null}
69	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
70	     */
71	    public String normalize(String telephone) {
72	        if (telephone == null) {
73	            return null;
74	        }
75	        boolean hasCountryCode = telephone.trim().startsWith("+");
76	        String digits = telephone.replaceAll("\\D", "");
77	        String nationalOrFull;
78	        if (hasCountryCode) {
79	            nationalOrFull = digits;
80	        } else {
81	            if (digits.startsWith("0")) {
82	                digits = digits.substring(1);
83	            }
84	            nationalOrFull = DEFAULT_COUNTRY_CODE + digits;
85	        }
86	        if (!nationalOrFull.matches("\\d{8,15}")) {
87	            throw new InvalidTelephoneException(
88	                "Telephone '" + telephone + "' cannot be normalized to a valid E.164 number");
89	        }
90	        return "+" + nationalOrFull;
91	    }
92	
93	    /**
94	     * Normalizes the supplied telephone to canonical E.164 form (see {@link #normalize(String)})
95	     * and additionally validates that its national-number length matches its country code:
96	     * {@code '+61'} requires 9 national digits and {@code '+1'} requires 10. This is the method to
97	     * use for a value supplied by a client on create/update; comparison of values already stored
98	     * should use {@link #normalize(String)}, which tolerates legacy numbers whose national length
99	     * predates this rule.
100	     *
101	     * @param telephone the raw telephone value (may be {@code null})
102	     * @return the normalized E.164 telephone, or {@code null} if the input was {@code null}
103	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
104	     *                                   national-number length is wrong for its country code
105	     */
106	    public String normalizeAndValidate(String telephone) {
107	        String e164 = normalize(telephone);
108	        if (e164 != null) {
109	            validateNationalNumberLength(telephone, e164.substring(1));
110	        }
111	        return e164;
112	    }
113	
114	    /**
115	     * Rejects a normalized number whose national-number length does not match the requirement for
116	     * its country code. Numbers whose country code is not in {@link #NATIONAL_DIGITS_BY_COUNTRY_CODE}
117	     * are left to the generic total-length rule enforced by {@link #normalize(String)}.
118	     *
119	     * @param telephone  the original raw value, for the error message
120	     * @param fullDigits the normalized digits (country code followed by the national number, no {@code '+'})
121	     */
122	    private void validateNationalNumberLength(String telephone, String fullDigits) {
123	        for (Map.Entry<String, Integer> entry : NATIONAL_DIGITS_BY_COUNTRY_CODE.entrySet()) {
124	            String countryCode = entry.getKey();
125	            if (fullDigits.startsWith(countryCode)) {
126	                int nationalDigits = fullDigits.length() - countryCode.length();
127	                if (nationalDigits != entry.getValue()) {
128	                    throw new InvalidTelephoneException(
129	                        "Telephone '" + telephone + "' has " + nationalDigits
130	                            + " national digits, but country code '+" + countryCode + "' requires "
131	                            + entry.getValue());
132	                }
133	                return;
134	            }
135	        }
136	    }
137	}
