17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DAILY_LIMIT_EXCEEDED = "The maximum number of owners that may be created today has been reached";
57	    private static final String ERROR_INVALID_TELEPHONE = "The supplied telephone number is not a valid E.164 number";
58	    private static final String ERROR_INVALID_ADDRESS = "The supplied address is blank after normalization";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
80	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
81	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
82	     * would catch it and report an authorization failure as a 500.
83	     *
84	     * @param e The {@link AccessDeniedException} to propagate
85	     * @throws AccessDeniedException always
86	     */
87	    @ExceptionHandler(AccessDeniedException.class)
88	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
89	        throw e;
90	    }
91	
92	    /**
93	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
94	     *
95	     * @param e The {@link Exception} to be handled
96	     * @param request {@link HttpServletRequest} object referring to the current request.
97	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
98	     */
99	    @ExceptionHandler(Exception.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
102	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
103	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
104	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
105	        return ResponseEntity.status(status).body(detail);
106	    }
107	
108	    /**
109	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
110	     * method returns a 404 Not Found status if an entity does not exist.
111	     *
112	     * @param e The {@link DataIntegrityViolationException} to be handled
113	     * @param request {@link HttpServletRequest} object referring to the current request.
114	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
115	     */
116	    @ExceptionHandler(DataIntegrityViolationException.class)
117	    @ResponseBody
118	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
119	        logger.warn("Data integrity violation at {} {}: {}",
120	            request.getMethod(),
121	            request.getRequestURI(),
122	            e.getMessage());
123	        logger.debug("Data integrity violation stacktrace", e);
124	        HttpStatus status = HttpStatus.NOT_FOUND;
125	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
126	        return ResponseEntity.status(status).body(detail);
127	    }
128	
129	    /**
130	     * Handles {@link OwnerConflictException}, the base type for every create-time rule that rejects
131	     * a new owner with a 409 Conflict (e.g. a duplicate identity key or a city at capacity),
132	     * returning a 409 Conflict status. The client-facing detail is taken from the
133	     * exception's {@link OwnerConflictException#getDetail()} so each rule keeps its own wording
134	     * while sharing this single handler.
135	     *
136	     * @param e The {@link OwnerConflictException} to be handled
137	     * @param request {@link HttpServletRequest} object referring to the current request.
138	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
139	     */
140	    @ExceptionHandler(OwnerConflictException.class)
141	    @ResponseBody
142	    public ResponseEntity<ProblemDetail> handleOwnerConflictException(OwnerConflictException e, HttpServletRequest request) {
143	        logger.warn("Owner conflict ({}) at {} {}: {}",
144	            e.getClass().getSimpleName(),
145	            request.getMethod(),
146	            request.getRequestURI(),
147	            e.getMessage());
148	        HttpStatus status = HttpStatus.CONFLICT;
149	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getDetail());
150	        return ResponseEntity.status(status).body(detail);
151	    }
152	
153	    /**
154	     * Handles {@link DailyOwnerLimitExceededException}, raised when an owner is created once 100 or
155	     * more owners have already been created today (compared by registration date), returning a
156	     * 429 Too Many Requests status.
157	     *
158	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
159	     * @param request {@link HttpServletRequest} object referring to the current request.
160	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
161	     */
162	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
163	    @ResponseBody
164	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
165	        logger.warn("Daily owner limit exceeded at {} {}: {}",
166	            request.getMethod(),
167	            request.getRequestURI(),
168	            e.getMessage());
169	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
170	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_EXCEEDED);
171	        return ResponseEntity.status(status).body(detail);
172	    }
173	
174	    /**
175	     * Handles {@link InvalidTelephoneException}, raised when a supplied telephone value cannot be
176	     * normalized to a valid E.164 number, returning a 400 Bad Request status.
177	     *
178	     * @param e The {@link InvalidTelephoneException} to be handled
179	     * @param request {@link HttpServletRequest} object referring to the current request.
180	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
181	     */
182	    @ExceptionHandler(InvalidTelephoneException.class)
183	    @ResponseBody
184	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
185	        logger.warn("Invalid telephone at {} {}: {}",
186	            request.getMethod(),
187	            request.getRequestURI(),
188	            e.getMessage());
189	        HttpStatus status = HttpStatus.BAD_REQUEST;
190	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_TELEPHONE);
191	        return ResponseEntity.status(status).body(detail);
192	    }
193	
194	    /**
195	     * Handles {@link InvalidAddressException}, raised when a supplied address value is blank after
196	     * normalization (and so carries no address), returning a 400 Bad Request status.
197	     *
198	     * @param e The {@link InvalidAddressException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
201	     */
202	    @ExceptionHandler(InvalidAddressException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
205	        logger.warn("Invalid address at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getMessage());
209	        HttpStatus status = HttpStatus.BAD_REQUEST;
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_ADDRESS);
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles exception thrown by Bean Validation on controller methods parameters
216	     *
217	     * @param e The {@link MethodArgumentNotValidException} to be handled
218	     * @param request {@link HttpServletRequest} object referring to the current request.
219	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
220	     */
221	    @ExceptionHandler(MethodArgumentNotValidException.class)
222	    @ResponseBody
223	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
224	        HttpStatus status = HttpStatus.BAD_REQUEST;
225	        BindingErrorsResponse errors = new BindingErrorsResponse();
226	        BindingResult bindingResult = e.getBindingResult();
227	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
228	        if (bindingResult.hasErrors()) {
229	            errors.addAllErrors(bindingResult);
230	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
231	                .map(fieldError -> {
232	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
233	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
234	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
235	                        fieldError.getField(),
236	                        defaultMessage,
237	                        rejectedValue);
238	                    return new ValidationMessageDto(message)
239	                        .putAdditionalProperty("field", fieldError.getField())
240	                        .putAdditionalProperty("rejectedValue", rejectedValue)
241	                        .putAdditionalProperty("defaultMessage", defaultMessage);
242	                })
243	                .toList();
244	            logger.debug("Validation error at {} {}: {}",
245	                request.getMethod(),
246	                request.getRequestURI(),
247	                bindingResult.getFieldErrors());
248	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
249	            detail.setProperty("errors", rejectedFieldNames(bindingResult));
250	            return ResponseEntity.status(status).body(detail);
251	        }
252	        return ResponseEntity.status(status).body(detail);
253	    }
254	
255	    /**
256	     * Collects the distinct names of the fields that failed validation, in the order they were
257	     * reported, so responses can list the offending fields (e.g. those that are missing or blank).
258	     *
259	     * @param bindingResult the {@link BindingResult} carrying the validation field errors
260	     * @return the distinct rejected field names
261	     */
262	    private List<String> rejectedFieldNames(BindingResult bindingResult) {
263	        return bindingResult.getFieldErrors().stream()
264	            .map(FieldError::getField)
265	            .distinct()
266	            .toList();
267	    }
268	
269	}
